with lines as (select id, host, level, latency_ms, k, attr_value from app_logs lateral view outer explode(context) e as k, attr_value) select *, round(latency_ms / sum(latency_ms) over (partition by k), 4) latency_ms_share, avg(latency_ms) over w_grp host_avg_latency_ms, round(latency_ms / sum(latency_ms) over (partition by host), 4) latency_ms_share_2 from lines window w_grp as (partition by host, level)
